def cite(key):
 n,u=sources[key];return f'<a class="source" href="{u}" target="_blank" rel="noopener">来源：{n} ↗</a>'
def p(text): return '<p>'+text+'</p>'
sections=[]
def section(id,kicker,title,body): sections.append(f'<section id="{id}"><div class="kicker">{kicker}</div><h2>{title}</h2>{body}</section>')
def chart(title,labels,values,unit,source,note,color='#1a756b'):
 mx=max(values)*1.15
 bars=''.join(f'<div class="barrow"><span>{l}</span><div class="track"><i style="width:{v/mx*100:.2f}%;background:{color}"></i></div><b>{v:g}{unit}</b></div>' for l,v in zip(labels,values))
 return f'<figure><figcaption>{title}</figcaption>{bars}<p class="note">{note} 横轴从0开始；条长按数值比例绘制。</p>{cite(source)}</figure>'
def diagram(title,items,note):
 return '<figure><figcaption>'+title+'</figcaption><div class="flow">'+''.join('<div>'+x+'</div>' for x in items)+'</div><p class="note">'+note+'</p></figure>'
section('question','01 / 研究问题','增长之后，谁来承担生活的风险？',p('一位退休老人需要住院，一个贫困家庭的孩子需要上学，一名失业工人需要收入。这些处境把抽象的“社会保障”变成同一个具体问题：收入中断或生活成本突然上升时，个人能向谁求助？约翰逊的“伟大社会”和中国社会保障的长期变化，都在重新安排政府、雇主、社区与家庭之间的责任。')+p('本报告的核心判断是：美国1960年代在既有社会保险与私人市场之上扩大公共责任；中国则经历了单位和集体保障的分层结构、市场化转轨中的重组，再到覆盖城乡的制度扩展。两者都有扩大保障的方向，却没有同一条起跑线、同一种改革工具或可以直接相加的成果。')+'<aside>阅读提示：美国主体为1963—1969年；中国按改革前、改革后的动荡与探索、2001年入世后三部分叙述。1978和2001是观察节点，不是所有制度同步改变的日期。</aside>')
section('us','02 / 美国的改革窗口','伟大社会：从机会到公共责任',p('约翰逊于1963年继任总统。战后经济增长并没有让贫困、种族隔离和医疗风险自行消失。民权运动把法律承诺与现实排斥之间的距离推到全国政治中心；1964年大选后的政治条件也为立法创造了窗口。总统的议会经验与协调能力重要，但把成果只写成一位政治家的意志，会抹去基层动员、国会谈判和长期制度积累。')+p('1964年5月的密歇根大学演说把目标放到城市、乡村和课堂：更富裕的国家还要考虑生活质量、自然环境与人的发展。它不是一部单独法案，而是一组国内改革议程。“向贫困宣战”属于其中，却不是全部。教育、医疗、公民权利、食品援助、城市和文化政策的相互连接，构成了这一议程的广度。')+cite('speech')+diagram('图1 · 改革的四条路径',['权利：打破制度性排斥','保险：分担医疗与老年风险','机会：教育、培训和早期发展','公共环境：城市、自然与文化'],'分析图解，不表示预算比例或各领域的量化权重。')+p('与新政相比，伟大社会并非从零建立福利国家。Social Security养老保险早于约翰逊；雇主医疗保险和州地方行政体系也已经存在。新改革的意义是在这些基础上增加制度层次、扩大进入服务的渠道，并让联邦拨款与反歧视要求发生联系。由此形成的体系也更复杂：不同人群依靠不同制度，联邦规则仍要穿过州、地方和服务提供者才能落地。'))
policies=[('医疗','Medicare / Medicaid','1965年创设，两套制度分别回应老年人医疗保险与符合条件低收入人群的医疗援助。后续资格和待遇有变化，不能把今天的制度原样投回1965年。'),('反贫困','经济机会与社区行动','就业培训、志愿服务、社区项目和早期教育把“改善机会”放在中心；它们不是一项统一现金收入保证。'),('教育','联邦资源进入课堂','面向贫困学生的基础教育支持、高等教育援助与Head Start扩展机会，但拨款不等于校际差距自动消失。'),('民权','1964 / 1965 / 1968','民权、投票权和公平住房立法改变法律边界；社会运动、执法与地方阻力决定权利能否转化为现实。'),('生活','食品、住房与城市','食品援助及城市政策处理基本生活与居住环境；住房供给、地方土地市场和种族隔离使执行更复杂。'),('公共文化','环境与传播','环境保护、艺术人文支持及公共广播拓展了“好社会”的定义，公共价值不能只用领取补贴人数衡量。')]
section('policy','03 / 政策地图','不是一张福利支票，而是一组制度工具','<div class="cards">'+''.join(f'<article><small>{a}</small><h3>{b}</h3><p>{c}</p></article>' for a,b,c in policies)+'</div>'+cite('medical')+cite('civil')+cite('vote')+p('医疗最能展示制度设计的政治逻辑。Medicare与社会保险传统相接，Medicaid则由联邦与州共同参与，针对符合条件的人群。它们扩大了公共筹资的角色，却没有把全部医疗服务改造成政府直接提供，也没有消除私人保险。资格、筹资和服务供给是三个不同问题：有人获得保险，并不意味着所有费用都不再由家庭承担。')+diagram('图2 · 从法律到实际保障',['国会立法与筹资规则','联邦部门与州执行','医院、学校和地方机构','个人实际获得服务'],'箭头表示执行链；每一环都可能产生资格、容量或地方差异。')+p('社区行动还揭示了参与与行政之间的矛盾：贫困者被邀请参与决定项目，但地方政府和既有机构未必愿意让渡权力。教育拨款也需要地方学校把资源转成教学能力。政策通过是重要起点，执行能力、服务质量和权力结构则决定最后一公里。'))
section('results','04 / 成效与争议','贫困下降是真实趋势，归因仍需克制',chart('图3 · 美国官方贫困率：历史节点',[1959,1969,1973,1980],[22.4,12.1,11.1,13.0],'％','poverty','全国人口，官方贫困口径；离散历史节点，不插值为完整年度序列。不是伟大社会的净政策效果。')+p('贫困率的下降说明1960年代确实发生了明显变化；但起点早于伟大社会，经济扩张、劳动市场、人口结构和其他收入保障安排都在起作用。官方贫困指标也并不完整计入所有非现金福利与税制影响，因此不能只凭这一条曲线就认定医疗、食品和住房政策的全部贡献。')+p('更扎实的评价需要逐领域拆开：医疗看覆盖和财务风险，也看实际就医；教育看进入机会，也看持续学习结果；民权看法律执行和政治参与，而不只看立法日期。一个项目即使没有消灭贫困，也可能减少疾病导致的家庭破产风险。反过来，覆盖扩大也不自动意味着服务质量和机会平等。')+p('批评来自不同方向。保守派强调财政负担、官僚效率和激励问题；左翼和基层倡议者则认为改革对收入、就业、住房和种族权力结构触及不足。这些是待检验的不同机制，不宜以一句“福利依赖”或“投入不足”替代证据。越南战争占用资源与政治注意力，城市冲突和种族反弹也侵蚀联盟；没有单一因素足以解释全部受挫。')+p('长期看，一些项目被重组或削减，另一些成为稳定制度。其重要遗产是公共医疗与教育责任难再被视为边缘事务。评价应允许两件事同时成立：制度保障显著扩大，而结构性不平等并没有因此消失。'))
section('cn1','05 / 中国 · 第一部分','改革开放前：单位、集体与家庭',p('改革开放前的社会保障并非一张覆盖所有人的同质网络。城镇正规就业者的保障往往与单位身份相连：劳动保险、退休待遇、医疗安排和住房等服务，共同嵌入劳动组织与分配体系。机关事业单位和企业之间也存在制度差别。工作单位不仅支付工资，还是生活资源的重要入口，因此失去或无法取得这种身份，意味着保障能力不同。')+p('农村更依赖家庭、集体经济和地方服务。合作医疗及基层卫生服务的价值，在于用相对有限资源组织基本防治；养老主要仍由家庭承担，困难群体救济则具有特定对象和地方条件。不能把某些集体或地区的良好经验写成全国同等的保障水平，也不能把缺少现代社会保险账户等同于完全没有互助和公共服务。')+cite('labour')+cite('health')+diagram('图4 · 改革前的分层入口',['城镇正规就业 → 单位保障','机关事业身份 → 相应公共安排','农村成员 → 集体服务＋家庭支持'],'分析示意：不是人数占比图；地区、职业与时期差异均存在。')+p('与伟大社会比较，区别首先是保障入口。美国新改革以年龄、收入和法定资格等条件扩大公共支持；中国的资源组织更紧密依附单位和集体。双方都存在分层，但分层轴线不同。美国的种族排斥不能简单等同于中国的城乡差异，中国单位保障也不能等同于美国私人雇主保险。比较的意义在于看身份如何影响风险分担，而不是把不同历史制度互换名称。'))
section('cn2','06 / 中国 · 第二部分','改革开放后的动荡、探索：旧保障松动，新制度形成',p('1978年后，生产组织、就业形态与人口流动逐步变化，保障也随之重组。农村集体筹资基础变化，使部分地区原有合作医疗安排承受压力；基层公共卫生、医疗服务和家庭付费之间的关系需要重新安排。城镇企业经营和用工方式变化，则暴露了“由本单位负责本单位职工”的局限：风险不能只由单个企业独自承受。')+p('到国企改制和下岗问题突出的阶段，工资、岗位与福利可能同时受到冲击。对个人而言，这不只是统计中的失业，也可能是医疗和养老预期的不稳定。对政府而言，需要在企业改革、基本生活与再就业之间建立衔接。下岗职工基本生活保障、失业保险与城市最低生活保障等安排体现了这种探索，但具体资格与地方执行能力并不一致。')+cite('labour')+p('新制度的形成不是一步完成。养老费用社会统筹的探索，逐渐推动责任越过企业边界；1997年企业职工基本养老保险改革与1998年城镇职工基本医疗保险改革，是重要全国性制度节点。统筹与个人缴费形成新的责任组合：保障不再只取决于本企业当期支付能力，但缴费记录、正式就业和地方管理边界又成为新的关键。')+cite('china')+p('因此，这个阶段既不能概括成“取消了所有福利”，也不能描述成无成本的效率改善。原有依附关系被削弱，一部分风险暴露给家庭；社会化统筹又为更大范围的风险共担创造基础。评价必须问：谁先获得新制度、谁在过渡中落空、成本由谁承担，以及流动人口和非正规就业者能否进入。')+diagram('图5 · 转轨中的责任重组',['单位独立负担','跨单位社会统筹','雇主＋个人缴费','公共财政与救助补位'],'制度路径概括；并非线性替代，家庭与单位责任持续存在。')+p('美国1960年代主要是在增长时期扩展联邦干预；中国这一阶段则把社会保障重建嵌入经济组织方式的深刻调整。两者都面对中央目标与地方执行的距离，但中国还必须处理原有就业—福利捆绑结构的解体与再建。只比较福利项目数量，会遗漏这种转轨成本。'))
section('cn3','07 / 中国 · 第三部分','入世之后：00、10与20年代的不同问题',p('2001年加入世界贸易组织是理解经济与就业环境的重要节点，但不能说新农合、居民养老或医保整合都是由入世单独造成。公共卫生事件、财政能力、城乡政策、人口结构和社会诉求共同推动改革；一些制度在入世前已有试点，另一些在十余年后才整合。')+'<h3>00年代：扩展与重建</h3>'+p('政策开始更明确地回应职工制度之外的广大人群。2003年后推进的新型农村合作医疗、2007年城镇居民医保试点及2009年新医改，分别从农村、城镇非就业居民和医药卫生体系入手。居民养老的探索也把原先主要依靠家庭的老年保障，逐步接入缴费与财政补助相结合的安排。它们扩大了保障入口，但个人缴费、报销范围与服务资源仍影响实际受益。')+cite('health')+'<h3>10年代：扩面、整合与制度化</h3>'+p('覆盖之外，制度间的边界变得更重要。社会保险法实施、城乡居民养老整合、城乡居民基本医保整合及救助衔接，体现了从“有没有项目”转向“项目能否连起来”。城乡身份、不同统筹地区与职工/居民制度之间的待遇差别，并不会因名称统一而马上消失。转移接续、异地结算和财政补助标准，直接关系流动人口与家庭的实际选择。')+'<h3>20年代：保障质量与可持续性</h3>'+p('疫情冲击提示，社会保障需要同时处理常态风险和突发事件；灵活就业、平台劳动和人口老龄化则让缴费连续性与待遇公平更加突出。年轻时工作地点和雇主不断变化的人，是否能积累稳定权益？长寿带来的医疗与照护需求由谁承担？这些问题把讨论从人数扩展推向保障深度、服务供给和筹资结构。')+p('本报告不将2020年代视为已经结束的历史，也不预测未确定的改革结果。下图采用已核查的2023年医保公报和2024年统计公报作为观察截面，不能替代截至2026年的全部政策更新。全国总量反映规模，不表示城乡、地区与就业群体待遇完全相同。')+chart('图6 · 2023年基本医保参保规模',['全国基本医保'],[13.3389],'亿人','insure','年末参保人数；这不是保障充分性或免费医疗比例。')+chart('图7 · 2024年基本养老参保结构',['城镇职工','城乡居民'],[5.3452,5.3830],'亿人','2024','年末制度参保人数，不是当年缴费人数或领取养老金人数；两类制度待遇不可按人数推定。'))
section('pressure','08 / 统计观察','覆盖之外：人口与公共服务也在变',chart('图8 · 中国人口老龄化：两次人口普查',['2010 · 60岁及以上','2020 · 60岁及以上','2010 · 65岁及以上','2020 · 65岁及以上'],[13.26,18.70,8.87,13.50],'％','age','全国人口年龄结构。2010数值由公报2020值减十年增幅还原；年龄组有包含关系，不可相加。')+p('老龄人口占比上升说明，养老筹资和长期照护问题不能仅用扩大参保人数回答。同样的参保规模，在年龄结构不同、就业质量不同和待遇标准不同的社会中，承载的责任并不相同。人口图不是福利“负担评分”，它说明的是风险结构发生了变化。')+chart('图9 · 劳动年龄人口平均受教育年限',['2010','2020'],[9.67,10.75],'年','edu','16—59岁人口；教育属于相关公共服务。变化不能单独归因于某项社保改革。','#b46d34')+p('教育提高既可能增强个人就业能力，也可能改变财政与社会保险的长期基础。但它不是医疗保险或养老金待遇。将教育、住房、养老和医疗统称为福利后直接求和，会混淆供给方式、受益阶段和计量单位。报告因此把相关公共服务单列，承认其联系，同时保留边界。'))
rows=[('覆盖入口','年龄、收入、就业及法定资格','单位、城乡、集体成员身份','职工保险扩展，过渡缺口突出','职工与居民体系并存，扩大覆盖'),('主要筹资','税收、保险缴费，联邦与州分工','国家、单位、集体与家庭','社会统筹＋单位个人缴费','财政补助＋缴费，多层次安排'),('医疗','公共保险叠加既有私人体系','公费、劳保与农村合作医疗','费用与筹资关系调整','基本医保与救助，关注待遇深度'),('养老','Social Security为既有基础','城镇退休，农村家庭养老','企业养老社会化与转轨责任','职工/居民制度，统筹与可携带性'),('救助','服务、食品及收入支持组合','特定对象救济与集体互助','下岗、失业、低保衔接','低保、专项救助及制度衔接'),('主要难题','种族与阶层差距，州际差异','身份分层和资源约束','新旧制度衔接，风险落到家庭','待遇差别、流动就业与老龄化')]
section('compare','09 / 核心比较','相似的问题，不同的制度路线','<div class="tablewrap"><table><caption>图10 · 社会风险分担的制度对照（定性比较）</caption><thead><tr><th>维度</th><th>美国伟大社会</th><th>中国改革前</th><th>中国转轨探索</th><th>中国入世后</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'+p('第一，共同点是市场收入并不足以覆盖全部生活风险，公共责任需要制度化。第二，制度入口不同：美国扩展年龄和收入资格，中国逐渐减轻对单一单位与城乡身份的依赖。第三，财政补助、保险缴费和家庭责任并非互斥，差别在于如何组合，以及经济困难时哪一方先承受压力。')+p('第四，法律承诺与实际服务之间都存在执行链。美国联邦—州关系与中国中央—地方关系不能等同，但都提醒我们，全国性政策并不自然产生地方均等服务。第五，参保广度、待遇深度与实际可及性是三个不同层次：覆盖率很高时，报销规则、个人负担和服务容量仍可能造成差异。')+'<aside>不做的比较：不把美国官方贫困率与中国官方贫困标准直接拼成排名；不把不同年代名义金额换算后当作生活水平；不把“制度存在”“已经参保”“得到足够服务”视为同一个指标。</aside>')
section('timeline','10 / 双轨时间线','把改革放回各自的时间中','<div class="timelines"><div><h3>美国 · 集中的立法窗口</h3>'+''.join(f'<details><summary>{y} · {t}</summary><p>{d}</p></details>' for y,t,d in [('1963','继任与社会运动','约翰逊继任，民权运动持续推动公共议题。'),('1964','伟大社会与民权改革','密歇根大学演说提出愿景；民权与反贫困立法推进。'),('1965','医疗、教育与投票权','Medicare和Medicaid签署；重要教育与投票权改革展开。'),('1966','医疗项目开始实施','从法案走向实际服务，需要行政准备、机构参与和执行能力。'),('1968','公平住房与政治危机','住房改革与战争、城市冲突及政治联盟变化并存。')])+'</div><div><h3>中国 · 跨数十年的重组</h3>'+''.join(f'<details><summary>{y} · {t}</summary><p>{d}</p></details>' for y,t,d in [('1978前','单位与集体','保障分层，城乡、身份和地区差异明显。'),('1978—2001','转轨与探索','生产就业结构改变；社会统筹、职工保险与救助制度逐步形成。'),('00年代','居民保障扩展','新农合、城镇居民医保、新医改及居民养老探索。'),('10年代','整合与制度化','城乡居民养老与医保整合、救助衔接，流动人口问题仍重要。'),('20年代','质量与可持续性','疫情、灵活就业、老龄化与照护需求推动新的讨论。')])+'</div></div><p class="note">点击节点展开；两列不是同年匹配。立法、试点与实施日期必须分别理解。</p>')
section('conclusion','11 / 结论与阅读方法','判断改革，先问它改变了谁的风险',p('伟大社会最持久的意义，是将医疗、教育与公民权利进一步纳入公共责任；其局限是，权利扩展和服务项目不能独自消除劳动、居住和财富结构中的不平等。中国的长期变化则显示，从单位集体依附转向更广泛社会统筹，可以扩大保障的组织边界，但转轨本身会产生缺口，覆盖扩大之后仍必须解决待遇、流动性与服务差异。')+p('因此，最有价值的比较不是谁的项目更多，而是谁有资格进入、谁实际支付、谁承担未被覆盖的费用、制度能否在失业或迁移时继续运作。稳定的社会保障并不只是一套财务账户，也需要行政能力、服务供给和清楚的公共责任。')+p('本报告将可核查的历史事实、描述性统计与作者的制度解释分开。条形图提供已核查节点及统计截面，不冒充连续年度数据库；图解只表示机制，不以面积暗示规模。尚未提供项目级因果估计，不能据这些图推算改革的净贡献。中国2020年代的政策仍在发展，后续更新应保留数据版本与制度口径。')+'<h3>术语速查</h3><dl><dt>社会保险</dt><dd>依法组织的风险共担安排，常与缴费、资格和待遇规则相连。</dd><dt>社会救助</dt><dd>针对符合困难条件群体的公共支持；通常与收入或需要评估有关。</dd><dt>公共服务</dt><dd>教育、卫生服务、住房支持等供给，不应全部归为保险待遇。</dd><dt>覆盖与可及性</dt><dd>前者回答是否进入制度，后者回答需要时能否实际取得服务。</dd></dl>')
section('sources','12 / 资料与数据','来源、口径与可下载数据','<p>下列资料优先使用官方原始文件和历史统计。官方制度叙述可证明政策安排，不应自动当作独立的效果评估。统计观察截至已核查的2024年材料，不声称涵盖2026年所有变化。</p><ol>'+''.join(f'<li><a href="{u}" target="_blank" rel="noopener">{n} ↗</a></li>' for n,u in sources.values())+'</ol><p><a href="data.json" download>下载图表数据与口径说明（JSON）</a> · <button onclick="window.print()">打印 / 保存PDF</button></p>')
